using System;using System.Linq;using System.Reflection;using HarborCity.RoadCore;
static class CityJunctionIndexChecks {
 static int checks;static void Check(bool v,string s){checks++;if(!v)throw new Exception(s);}
 static (World world,int center,int west,int east,int south,int north,int w,int e,int s,int n) Cross(){var a=new World();int j=a.AddJunction(new Point()),w=a.AddJunction(new Point(-60,0,0)),e=a.AddJunction(new Point(60,0,0)),s=a.AddJunction(new Point(0,0,-60)),n=a.AddJunction(new Point(0,0,60));int rw=a.AddRoad(w,j,new[]{a.JunctionPosition(w),a.JunctionPosition(j)}),re=a.AddRoad(j,e,new[]{a.JunctionPosition(j),a.JunctionPosition(e)}),rs=a.AddRoad(s,j,new[]{a.JunctionPosition(s),a.JunctionPosition(j)}),rn=a.AddRoad(j,n,new[]{a.JunctionPosition(j),a.JunctionPosition(n)});return(a,j,a.AddDepot(w),a.AddDepot(e),a.AddDepot(s),a.AddDepot(n),rw,re,rs,rn);}
 static void Main(){var f=Cross();long ew=Network.ConnectionId(Network.LaneId(f.w,false),Network.LaneId(f.e,false)),sn=Network.ConnectionId(Network.LaneId(f.s,false),Network.LaneId(f.n,false));var claims=new JunctionReservations(f.world.Network);
  claims.Reserve(f.center,ew,1);Check(!claims.CanReserve(f.center,sn,2),"Physical claim lost conflict");claims.ReserveTemporary(f.center,ew,1);Check(claims.CopyClaims().Count==1,"Duplicate owner/path across layers");claims.ClearTemporary();Check(!claims.CanReserve(f.center,sn,2),"Clearing speculative claims removed physical state");claims.RemovePhysical(f.center,ew,1);claims.ReserveTemporary(f.center,ew,1);Check(!claims.CanReserve(f.center,sn,2),"Speculative claim lost conflict");claims.ClearTemporary();Check(claims.CanReserve(f.center,sn,2),"Speculative claim leaked across refresh");bool missing=false;try{claims.RemovePhysical(f.center,ew,1);}catch(InvalidOperationException){missing=true;}Check(missing,"Missing physical ownership silently accepted");
  f.world.Dispatch(f.west,f.east);f.world.Dispatch(f.south,f.north);var cold=SaveCodec.Read(SaveCodec.Write(f.world));
  for(int i=0;i<600;i++){f.world.Step();cold.Step();f.world.AssertJunctionIndex();cold.AssertJunctionIndex();Check(SaveCodec.Write(f.world).SequenceEqual(SaveCodec.Write(cold)),"Junction update changed cold movement/settlement");}
  Check(f.world.Delivered==2&&f.world.JunctionChanges>0,"No real junction traversal tested");
  var quiet=Cross();int src=quiet.west,dst=quiet.east;quiet.world.RegisterAccess(src,Network.LaneId(quiet.w,false),20);quiet.world.RegisterAccess(dst,Network.LaneId(quiet.e,false),40);var v=quiet.world.Dispatch(src,dst);Check(v.distance==20,"Midroad fixture did not use explicit accesses");quiet.world.AssertJunctionIndex();long changes=quiet.world.JunctionChanges;for(int i=0;i<10;i++){quiet.world.Step();quiet.world.AssertJunctionIndex();}Check(v.distance>20&&quiet.world.JunctionChanges==changes,"Ordinary midroad progress rewrites junction claims");
  // Deliberately bypass movement notification. Compare before any full validator.
  var bad=Cross();var actor=bad.world.Dispatch(bad.west,bad.east);for(int i=0;i<500&&actor.indexedJunction==0;i++){bad.world.Step();bad.world.AssertJunctionIndex();}Check(actor.indexedJunction!=0,"Negative control never entered protected area");int last=actor.Route.Count-1;actor.CommitPosition(actor.Route[last],20,last);typeof(World).GetField("indexDirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(bad.world,true);bool caught=false;try{bad.world.AssertJunctionIndex();}catch(InvalidOperationException e){caught=e.Message.Contains("junction");}Check(caught,"Independent nonrepairing oracle missed bypassed claim notification");
  // The removed per-refresh endpoint scan is replaced by the existing
  // structural invalidation boundary, including actors not otherwise moving.
  var city=HarborCity.CityCoreIndustrySession.Create();var member=city.Entities.Members[0].Person;var commuter=city.Simulation.RequestCommute(member.id,3,1);Check(commuter!=null,"Endpoint lifecycle fixture did not dispatch");city.Advance(.05);double oldDistance=commuter.distance;city.Transport.SetEndpointAvailable(1,false);city.Transport.AssertJunctionIndex();Check(commuter.status==VehicleStatus.Stranded&&commuter.distance==oldDistance,"Endpoint removal lost freeze/safety semantics");city.Transport.SetEndpointAvailable(1,true);city.Transport.AssertJunctionIndex();Check(commuter.status==VehicleStatus.Stranded,"Endpoint reopen silently resumed vehicle");
  Console.WriteLine("PASS "+checks+" layer/600-step exact cold/crossing/midroad-noop/missing-notification controls");
 }
}
